Definition iv_disjoint (p q : word * word) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S5;A1;o3;Y6;00;A1;i74;#0;A2;i73;#1;#1;A2;k2;#0;A3;k78;#1;#1;r2;A2;k2;#0;A3;k78;#1;#1;r1;Lp;R#2;Lq;R#2;A2;i84;A2;k11;A2;k9;#3;A2;k2;#0;A3;k80;#1;#1;r2;#4;A2;k11;A2;k9;#4;A2;k2;#0;A3;k80;#1;#1;r1;#3;").
Inductive seps : list (word * word) -> Prop :=
| seps_nil : seps []
| seps_cons : forall p l, Forall (iv_disjoint p) l -> seps l -> seps (p :: l).

Fixpoint sum_sizes (l : list (word * word)) : Z :=
  match l with [] => 0 | iv :: r => bv_unsigned (snd iv) + sum_sizes r end.

