Definition is_havoc (lo hi : nat) (t : expr) : option nat := ltac2:(Rpl.RP.run_k (rplG ()) 3 "S2;A1;i87;i94;A1;o49;i94;Llo;Ri94;Lhi;Ri94;Lt;Ri1;m1;RNLt;Ri1;#0;r1;8;Lz;Ri5;#1;Lv;Ri94;m61;RNL~Ri61;#0;A2;k76;A2;k382;r4;r1;A2;k859;r1;r3;2;A2;o166;i94;r1;#1;Lop;Ri525;La;Ri1;Lb;Ri1;#1;Lop;Ri525;La;Ri1;Lb;Ri1;#1;Lop;Ri526;La;Ri1;Lb;Ri1;#1;Lop;Ri526;La;Ri1;Lb;Ri1;#1;Lsx;Ri61;Llo0;Ri94;Ln;Ri94;Le;Ri1;#1;Lsx;Ri61;Lk;Ri94;Li;Ri5;Ln;Ri94;#1;").

Fixpoint henv (lo hi : nat) (E : env) (rs ts : list expr) : env :=
  match rs, ts with
  | r :: rs', t :: ts' =>
      let E1 := henv lo hi E rs' ts' in
      match is_havoc lo hi t with Some v => upd E1 v (edenot E r) | None => E1 end
  | _, _ => E
